const a = 2n ** 61n - 17n;
const exact = a * 3n;
const n = Number(exact);
console.log(JSON.stringify({exact: exact.toString(), number: n, safeInteger: Number.isSafeInteger(n), roundTripEquals: BigInt(n) === exact, representableSpacingNear: 2 ** (Math.floor(Math.log2(Number(exact))) - 52)}));

const numResult = (2 ** 61 - 17) * 3;
const exactBig = (2n ** 61n - 17n) * 3n;
console.log("Number result:", numResult);
console.log("Number result (exact integer string):", BigInt(numResult).toString());
console.log("BigInt exact result:", exactBig.toString());
console.log("Equal?", BigInt(numResult) === exactBig);
console.log("Difference:", (exactBig - BigInt(numResult)).toString());
console.log("Number.isSafeInteger(numResult):", Number.isSafeInteger(numResult));
